<script>
    // 保留这个函数定义不变
    function SafeGetValue(obj, path, defaultValue = "N/A") {
        let keys = Array.isArray(path) ? path : path.split('.');
        let current = obj;
        for (let i = 0; i < keys.length; i++) {
            if (current === undefined || current === null || typeof current !== 'object' || !current.hasOwnProperty(keys[i])) {
                return defaultValue;
            }
            current = current[keys[i]];
        }
        if (current === undefined || current === null) {
            return defaultValue;
        }
        // 修正：明确处理布尔值和数组情况
        if (Array.isArray(current)) {
            return current.length > 0 ? current[0] : defaultValue; // 返回数组第一个元素或默认值
        }
        // 其他情况直接返回，包括布尔值
        return current;
    }

    // 保留这个函数内部逻辑不变
    function updateProgressBar(barId, valueMainId, valueDescId, rawValueFromCharacterData, min, max, color) {
        const progressBar = document.getElementById(barId);
        const valueMainDisplay = document.getElementById(valueMainId);
        const valueDescDisplay = document.getElementById(valueDescId);

        // ---- Start of preserved logic ----
        if (!valueMainDisplay) {
            return;
        }

        let displayString = String(rawValueFromCharacterData); // Convert raw value to string initially
        let oldValue = min;
        let newValue = min;
        let descriptionText = "";
        let isUpdate = false;

        // Attempt to extract description like "(...)" from the end
        const descMatch = displayString.match(/\s*\((.+)\)\s*$/);
        if (descMatch && descMatch[1]) {
            descriptionText = descMatch[1];
            displayString = displayString.substring(0, descMatch.index).trim();
        }

        // Check for "->" update indicator
        const parts = displayString.split('->');
        if (parts.length === 2) {
            const parsedOld = parseFloat(parts[0].trim());
            const parsedNew = parseFloat(parts[1].trim());
            if (!isNaN(parsedOld) && !isNaN(parsedNew)) {
                oldValue = parsedOld;
                newValue = parsedNew;
                isUpdate = true;
                valueMainDisplay.innerHTML = `${oldValue}<span class="update-arrow">→</span>${newValue}`;
                valueMainDisplay.className = 'value-main'; // Reset class
            } else {
                valueMainDisplay.innerText = displayString; // Show original if parsing fails
                 valueMainDisplay.className = 'value-main'; // Reset class
                const fallbackValue = parseFloat(parts[0].trim());
                 if (!isNaN(fallbackValue)) {
                     oldValue = fallbackValue;
                 }
                newValue = oldValue;
            }
        } else {
            const parsedValue = parseFloat(displayString);
            if (!isNaN(parsedValue)) {
                oldValue = parsedValue;
                newValue = parsedValue;
                valueMainDisplay.innerText = String(newValue);
                 valueMainDisplay.className = 'value-main'; // Reset class
            } else {
                // If not a number and not an update, display as string
                valueMainDisplay.innerText = displayString;
                 valueMainDisplay.className = 'value-main'; // Reset class
                // No valid number for progress bar, use min
                oldValue = min;
                newValue = min;
            }
        }

        // Set description tex if exists
        if (valueDescDisplay) {
            valueDescDisplay.innerText = descriptionText ? `(${descriptionText})` : "";
        }

        // Set progress bar width based on OLD value
        if (progressBar) {
            let valueForProgress = oldValue;
            valueForProgress = Math.max(min, Math.min(max, valueForProgress));
            const range = max - min;
            const percentage = range === 0 ? (valueForProgress >= max ? 100 : 0) : ((valueForProgress - min) / range) * 100;
            progressBar.style.width = `${Math.max(0, Math.min(100, percentage))}%`;
            if (color) {
                progressBar.style.backgroundColor = color;
            } else {
                progressBar.style.backgroundColor = 'var(--accent-secondary)'; // Default color
            }
        }
        // ---- End of preserved logic ----
    }

    // 主要修改此函数
    async function initDisplay() {
        try {
            const messages = await getChatMessages(getCurrentMessageId());
            if (!messages || messages.length === 0 || !messages[0].data) {
                document.getElementById('status-card').innerHTML = "<p style='color:red; padding:10px;'>无法加载状态数据 (messages empty)</p>";
                return;
            }
            const gameData = messages[0].data;
            const characterData = gameData.display_data || gameData.stat_data;
            if (!characterData) {
                 document.getElementById('status-card').innerHTML = "<p style='color:red; padding:10px;'>无法加载状态数据 (characterData missing)</p>";
                 return;
            }

            const characterKey = "零"; // 确保这是正确的键名

            // 更新世界信息
            const worldDateElement = document.getElementById('world-date');
            const worldTimeElement = document.getElementById('world-time');
            if (worldDateElement) worldDateElement.innerText = SafeGetValue(characterData, '日期', '--月--日');
            if (worldTimeElement) worldTimeElement.innerText = SafeGetValue(characterData, '时间', '--:--');

            const weatherElement = document.getElementById('world-weather');
            const eventElement = document.getElementById('world-event');
            if (characterData.hasOwnProperty('世界')) {
                 const worldData = characterData['世界'];
                 if (weatherElement) weatherElement.innerText = SafeGetValue(worldData, '当前天气', '未知');
                 if (eventElement) eventElement.innerText = SafeGetValue(worldData, '特殊事件标记', '无');
             } else {
                 if (weatherElement) weatherElement.innerText = 'N/A';
                 if (eventElement) eventElement.innerText = 'N/A';
             }


            // 更新角色“零”的信息
            if (characterData.hasOwnProperty(characterKey)) {
                const reiData = characterData[characterKey];

                // 处理数值和进度条
                updateProgressBar('rei-affection-bar', 'rei-affection', 'rei-affection-desc', SafeGetValue(reiData, '好感度'), 0, 100, 'var(--accent-primary)');
                updateProgressBar('rei-loverate-bar', 'rei-loverate', 'rei-loverate-desc', SafeGetValue(reiData, '恋人度'), 0, 100, 'var(--loverate-color)');
                updateProgressBar('rei-renjidu-bar', 'rei-renjidu', 'rei-renjidu-desc', SafeGetValue(reiData, '人机度'), 0, 100, 'var(--accent-secondary)');
                updateProgressBar('rei-shyness-bar', 'rei-shyness', 'rei-shyness-desc', SafeGetValue(reiData, '害羞度'), 0, 100, 'var(--shyness-color)');
                updateProgressBar('rei-lust-bar', 'rei-lust', 'rei-lust-desc', SafeGetValue(reiData, '性欲'), 0, 100, 'var(--lust-color)');
                updateProgressBar('rei-socialtask-bar', 'rei-socialtask', 'rei-socialtask-desc', SafeGetValue(reiData, '社交尝试任务进度'), 0, 100, 'var(--socialtask-color)');

                // 单独处理布尔值：处女状态
                 const virginStatusElement = document.getElementById('rei-virginstatus');
                 const virginStatusDescElement = document.getElementById('rei-virginstatus-desc');
                 if (virginStatusElement) {
                     const virginStatusValue = SafeGetValue(reiData, '处女状态', true); // 获取布尔值
                     if (typeof virginStatusValue === 'boolean') {
                         virginStatusElement.innerText = virginStatusValue ? "是" : "否";
                         virginStatusElement.className = 'value-main ' + (virginStatusValue ? 'status-true' : 'status-false');
                     } else {
                         virginStatusElement.innerText = String(virginStatusValue); // fallback
                         virginStatusElement.className = 'value-main';
                     }
                 }
                 if (virginStatusDescElement) virginStatusDescElement.innerText = ""; // 清空描述

                // 处理纯文本：内心想法
                const innerThoughtElement = document.getElementById('rei-innerthought');
                const innerThoughtDescElement = document.getElementById('rei-innerthought-desc');
                 if (innerThoughtElement) {
                     innerThoughtElement.innerText = SafeGetValue(reiData, '内心想法', '...');
                 }
                 if(innerThoughtDescElement) innerThoughtDescElement.innerText = ""; // 清空描述


            } else {
                 // 清理所有“零”相关的字段
                 const idsToClear = ['rei-affection', 'rei-loverate', 'rei-renjidu', 'rei-shyness', 'rei-lust', 'rei-virginstatus', 'rei-socialtask', 'rei-innerthought'];
                 idsToClear.forEach(id => {
                     const el = document.getElementById(id);
                     if (el) {
                        el.innerText = 'N/A';
                        el.className = 'value-main'; // Reset class
                     }
                 });
                 const descIdsToClear = ['rei-affection-desc', 'rei-loverate-desc', 'rei-renjidu-desc', 'rei-shyness-desc', 'rei-lust-desc', 'rei-virginstatus-desc', 'rei-socialtask-desc', 'rei-innerthought-desc'];
                 descIdsToClear.forEach(id => {
                     const el = document.getElementById(id);
                     if (el) el.innerText = '(数据缺失)';
                 });
                 const barIdsToReset = ['rei-affection-bar', 'rei-loverate-bar', 'rei-renjidu-bar', 'rei-shyness-bar', 'rei-lust-bar', 'rei-socialtask-bar'];
                 barIdsToReset.forEach(id => {
                     const el = document.getElementById(id);
                     if (el) el.style.width = '0%';
                 });
            }

             // 默认展开第一个section
             const firstSectionHeader = document.querySelector('.section:nth-of-type(1) .section-header');
             if (firstSectionHeader) {
                const content = firstSectionHeader.nextElementSibling;
                if (content && !content.classList.contains('expanded')) {
                     toggleSection(firstSectionHeader);
                }
             }

        } catch (error) {
            document.getElementById('status-card').innerHTML = `<p style='color:red; padding:10px;'>状态栏加载出错: ${error.message || '未知错误'}</p>`;
        }
    }

    // 保留这个函数定义不变
    function toggleSection(element) {
        const content = element.nextElementSibling;
        const arrow = element.querySelector('span:last-child');
        if (!content || !arrow) return;
        const isExpanded = content.classList.toggle('expanded');
        element.classList.toggle('expanded-header', isExpanded);
        arrow.innerText = isExpanded ? '▲' : '▼';
    }

    document.addEventListener('DOMContentLoaded', initDisplay);
</script>
</body>
