<script>
    function SafeGetValue(obj, path, defaultValue = "N/A") {
        let keys = Array.isArray(path) ? path : path.split('.');
        let current = obj;
        for (let i = 0; i < keys.length; i++) {
            if (current === undefined || current === null || typeof current !== 'object' || !current.hasOwnProperty(keys[i])) {
                return defaultValue;
            }
            current = current[keys[i]];
        }
        if (current === undefined || current === null) {
            return defaultValue;
        }
        /* Modified: Always return the raw value (could be array or primitive) */
        return current;
    }

    function updateProgressBar(barId, rawValue, min, max, color) {
        const progressBar = document.getElementById(barId);
        if (!progressBar) return;

        let numericValue = min;
        let valueToParse = rawValue;

        if (Array.isArray(rawValue) && rawValue.length > 0) {
            valueToParse = rawValue[0];
        }

        const parsedValue = parseFloat(String(valueToParse));
        if (!isNaN(parsedValue)) {
            numericValue = parsedValue;
        }

        numericValue = Math.max(min, Math.min(max, numericValue));
        const range = max - min;
        const percentage = range === 0 ? (numericValue >= max ? 100 : 0) : ((numericValue - min) / range) * 100;
        progressBar.style.width = `${Math.max(0, Math.min(100, percentage))}%`;
        progressBar.style.backgroundColor = color || 'var(--accent-secondary)';
    }

    async function initDisplay() {
        try {
            const messages = await getChatMessages(getCurrentMessageId());
            if (!messages || messages.length === 0 || !messages[0].data) {
                document.getElementById('status-card').innerHTML = "<p style='color:red; padding:10px;'>无法加载状态数据 (messages empty)</p>";
                return;
            }
            const gameData = messages[0].data;
            const characterData = gameData.display_data || gameData.stat_data;
            if (!characterData) {
                 document.getElementById('status-card').innerHTML = "<p style='color:red; padding:10px;'>无法加载状态数据 (characterData missing)</p>";
                 return;
            }

            const characterKey = "零";

            /* Helper to update main value text (no description handling needed now) */
            function updateMainValue(mainId, fullPath, isBoolean = false, defaultVal = 'N/A', trueText = '是', falseText = '否') {
                const mainEl = document.getElementById(mainId);
                if (!mainEl) return;

                const rawValueArr = SafeGetValue(characterData, fullPath, null); /* Pass null as default */
                let displayValue = defaultVal;
                let boolResult = false;

                if (rawValueArr !== null && Array.isArray(rawValueArr)) {
                    if (rawValueArr.length > 0) {
                        const actualValue = rawValueArr[0];
                        if (isBoolean) {
                            boolResult = actualValue === true;
                            displayValue = boolResult ? trueText : falseText;
                        } else {
                            displayValue = String(actualValue);
                        }
                    } else {
                         /* Handle empty array - display default appropriate for type */
                         if (isBoolean) {
                            boolResult = defaultVal === true; /* Check default */
                            displayValue = boolResult ? trueText : falseText;
                         } else {
                             displayValue = String(defaultVal);
                         }
                    }
                } else if (rawValueArr !== null) { /* Handle non-array value, if it occurs */
                      if (isBoolean) {
                          boolResult = rawValueArr === true;
                          displayValue = boolResult ? trueText : falseText;
                      } else {
                           displayValue = String(rawValueArr);
                      }
                } else { /* Value is missing or null */
                     console.warn(`Data at ${fullPath} is missing or null. Using default.`);
                      if (isBoolean) {
                         boolResult = defaultVal === true;
                         displayValue = boolResult ? trueText : falseText;
                      } else {
                          displayValue = String(defaultVal);
                      }
                }

                mainEl.innerText = displayValue;
                if (isBoolean) {
                    mainEl.className = 'value-main ' + (boolResult ? 'status-true' : 'status-false');
                }
            }

            /* --- Update World Info --- */
            updateMainValue('world-date', '日期', false, '--月--日');
            updateMainValue('world-time', '时间', false, '--:--');

            if (characterData.hasOwnProperty('世界')) {
                updateMainValue('world-weather', '世界.当前天气', false, '未知');
                updateMainValue('world-event', '世界.特殊事件标记', false, '无');
            } else {
                 document.getElementById('world-weather').innerText = 'N/A';
                 document.getElementById('world-event').innerText = 'N/A';
            }

            /* --- Update Character Info --- */
            if (characterData.hasOwnProperty(characterKey)) {
                /* Variables with Progress Bars */
                const variablesToUpdate = [
                     { id: 'rei-haogandu', path: '零.好感度', min: 0, max: 100, color: 'var(--accent-primary)', defaultArr: [10, ''] },
                     /* { id: 'rei-lianrendu', path: '零.恋人度', min: 0, max: 100, color: 'var(--loverate-color)', defaultArr: [0, ''] }, Removed */
                     { id: 'rei-tiaojiaozhi', path: '零.调教值', min: 0, max: 100, color: 'var(--traininglevel-color)', defaultArr: [0, ''] },
                     { id: 'rei-renjidu', path: '零.人机度', min: 0, max: 100, color: 'var(--accent-secondary)', defaultArr: [95, ''] },
                     { id: 'rei-haixiudu', path: '零.害羞度', min: 0, max: 100, color: 'var(--shyness-color)', defaultArr: [5, ''] },
                     { id: 'rei-xingyu', path: '零.性欲', min: 0, max: 100, color: 'var(--lust-color)', defaultArr: [5, ''] },
                     { id: 'rei-shejiaochangshi', path: '零.社交尝试任务进度', min: 0, max: 100, color: 'var(--socialtask-color)', defaultArr: [10, ''] }
                 ];

                 variablesToUpdate.forEach(v => {
                     const rawValueArr = SafeGetValue(characterData, v.path, v.defaultArr);
                     updateMainValue(v.id, v.path, false, v.defaultArr[0]); /* Update text value */
                     updateProgressBar(v.id + '-bar', rawValueArr, v.min, v.max, v.color); /* Update progress bar */
                 });

                 /* Boolean Values */
                updateMainValue('rei-chunvzhuangtai', '零.处女状态', true, true); /* Default true */

                 /* Text Values */
                updateMainValue('rei-neixinxiangfa', '零.内心想法', false, '...'); /* Default ... */

            } else {
                 console.warn(`Status bar: '${characterKey}' data not found.`);
                 const idsToClear = ['rei-haogandu', /*'rei-lianrendu',*/ 'rei-tiaojiaozhi', 'rei-renjidu', 'rei-haixiudu', 'rei-xingyu', 'rei-chunvzhuangtai', 'rei-shejiaochangshi', 'rei-neixinxiangfa'];
                 idsToClear.forEach(id => {
                     const el = document.getElementById(id);
                     if (el) el.innerText = 'N/A';
                 });
                 const barIdsToReset = ['rei-haogandu-bar', /*'rei-lianrendu-bar',*/ 'rei-tiaojiaozhi-bar', 'rei-renjidu-bar', 'rei-haixiudu-bar', 'rei-xingyu-bar', 'rei-shejiaochangshi-bar'];
                 barIdsToReset.forEach(id => {
                     const el = document.getElementById(id);
                     if (el) el.style.width = '0%';
                 });
            }

            /* Default Expand First Section */
            const firstSectionHeader = document.querySelector('.section:nth-of-type(1) .section-header');
            if (firstSectionHeader) {
                const content = firstSectionHeader.nextElementSibling;
                 if (content && !content.classList.contains('expanded')) {
                     toggleSection(firstSectionHeader);
                }
            }

        } catch (error) {
            console.error("Error initializing status display:", error);
            document.getElementById('status-card').innerHTML = `<p style='color:red; padding:10px;'>状态栏加载时出错: ${error.message}</p>`;
        }
    }

    function toggleSection(element) {
        const content = element.nextElementSibling;
        const arrow = element.querySelector('span:last-child');
        if (!content || !arrow) return;
        const isExpanded = content.classList.toggle('expanded');
        element.classList.toggle('expanded-header', isExpanded);
        arrow.innerText = isExpanded ? '▲' : '▼';
    }

    document.addEventListener('DOMContentLoaded', initDisplay);
</script>
